import {test,expect,type Page} from '@playwright/test';
import {readFile} from 'node:fs/promises';
import {createProject,createEntity,textToRichText,newId} from '../../src/domain/model';
import {createWorldSnapshot} from '../../src/domain/world';
import {exportScenario,inspectScenario} from '../../src/storage/archive';
import {unzipSync,strFromU8} from 'fflate';
import {mkdtemp,writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
import type {ProjectData} from '../../src/domain/types';
import {prepareAsset} from '../../src/domain/attachments';
async function nav(page:Page,name:RegExp){const menu=page.getByRole('button',{name:'メニューを開く'});if(await menu.isVisible())await menu.click();await page.getByRole('button',{name}).first().click();}
async function seed(page:Page,p:ProjectData,assets:Record<string,Uint8Array>={}){await page.goto('./');await page.getByRole('button',{name:'保存ファイルを読み込む',exact:true}).click();await page.locator('input[type=file]').setInputFiles({name:'handoff.scenario',mimeType:'application/zip',buffer:Buffer.from(await exportScenario(p,{loadAsset:hash=>assets[hash]}))});await page.getByLabel('復元方法と対象への影響を確認しました').check();await page.getByRole('button',{name:'この内容で復元する',exact:true}).click();await expect(page.locator('.project-switch')).toBeVisible();}
async function backup(page:Page){await nav(page,/^作品・保存/);await page.getByRole('tab',{name:'完全保存・復元',exact:true}).click();const pending=page.waitForEvent('download');await page.getByRole('button',{name:'完全保存ファイルを作成',exact:true}).click();return inspectScenario(new Uint8Array(await readFile((await (await pending).path())!)),{worker:false});}
async function quota(page:Page){await page.evaluate(()=>{const put=IDBObjectStore.prototype.put;let fail=true;IDBObjectStore.prototype.put=function(...args:Parameters<IDBObjectStore['put']>){if(fail&&this.name==='projects'){fail=false;throw new DOMException('fixture quota','QuotaExceededError');}return put.apply(this,args);};});}
async function production(page:Page){await nav(page,/^構成/);await page.getByRole('tab',{name:'制作',exact:true}).click();}
async function output(page:Page){await nav(page,/^作品・保存/);await page.getByRole('tab',{name:'目的別出力',exact:true}).click();}
async function holdFileRead(page:Page,name:string){await page.evaluate(name=>{const original=File.prototype.arrayBuffer;File.prototype.arrayBuffer=function(){if(this.name!==name)return original.call(this);const file=this;return new Promise<ArrayBuffer>(resolve=>{(window as unknown as {releaseFileRead:()=>void}).releaseFileRead=()=>{void original.call(file).then(resolve);};});};},name);}
async function releaseFileRead(page:Page){await page.evaluate(()=>(window as unknown as {releaseFileRead:()=>void}).releaseFileRead());}
function story(){const p=createProject('受渡しの通常操作'),scene=createEntity(p.projectId,'scene','制作する場面',{body:textToRichText('😀門で勝利を確かめる')}),line=createEntity(p.projectId,'dialogue_line','受渡し台詞',{text:textToRichText('😀帰ってきた')}),task=createEntity(p.projectId,'production_task','場面の実装',{targetIds:[scene.id],stage:'implementation',progress:'doing',deadline:{date:'2026-10-10',timeZone:'Asia/Tokyo'}}),entry=createEntity(p.projectId,'flow_node','ゲーム入口',{nodeType:'automatic',executionPolicy:'first_match',sceneId:scene.id}),terminal=createEntity(p.projectId,'flow_node','ゲーム終端',{nodeType:'terminal',terminalReason:'完了'}),edge=createEntity(p.projectId,'flow_edge','ゲーム進行',{fromId:entry.id,toId:terminal.id,edgeType:'automatic'}),graph=createEntity(p.projectId,'flow_graph','ゲーム経路',{nodeIds:[entry.id,terminal.id],entryIds:[entry.id],exitIds:[terminal.id],edgeIds:[edge.id]});scene.data.dialogueLineIds=[line.id];p.entities.push(scene,line,task,entry,terminal,edge,graph);p.entities.forEach(e=>e.status='confirmed');return {p,scene,line,task,entry,edge,terminal};}
function publicPolicy(p:ProjectData){const selected=p.entities.filter(e=>['scene','dialogue_line','flow_node','flow_edge','flow_graph','external_contract'].includes(e.kind)),publicTexts=Object.fromEntries(selected.map(e=>[e.id,Object.fromEntries(Object.entries(e.data).filter(([field,value])=>value!=null&&['body','text','key','label','terminalReason','description'].includes(field)).map(([field,value])=>[field,Array.isArray(value)?value.map(block=>({...block,id:newId()})):value]))]));const profile=createEntity(p.projectId,'projection_profile','確認したゲーム公開範囲',{audience:'reader',publicTitle:'公開したゲーム',publicVersionLabel:'公開一版',includedIds:selected.map(e=>e.id),allowedKinds:[...new Set(selected.map(e=>e.kind))],idPolicy:'preserve',namePolicy:{defaultPolicy:{mode:'replace',replacement:'公開対象'}},publicTexts});profile.status='confirmed';p.entities.push(profile);return profile;}

test('制作見積の入力を移動とcold再開から保持し、quota拒否後の原子保存を完全ファイルへつなぐ',async({page})=>{const f=story();await seed(page,f.p);await production(page);let panel=page.locator('.production-planning');await expect(panel).toContainText('固有場面 1');await panel.getByLabel('見積する制作タスク',{exact:true}).selectOption(f.task.id);await panel.getByLabel('一作業日の固有件数',{exact:true}).fill('2');await panel.getByLabel('見積の仮定',{exact:true}).fill('場面と台詞を固有件数で一度だけ制作');await nav(page,/^資料/);await production(page);await expect(panel.getByLabel('一作業日の固有件数',{exact:true})).toHaveValue('2');await page.reload();await production(page);panel=page.locator('.production-planning');await expect(panel.getByLabel('見積の仮定',{exact:true})).toHaveValue('場面と台詞を固有件数で一度だけ制作');await panel.getByRole('button',{name:'制作見積を確認',exact:true}).click();await expect(panel).toContainText('1作業日');await quota(page);await panel.getByRole('button',{name:'確認した制作見積を保存',exact:true}).click();await expect(panel.getByRole('alert')).toContainText('容量');await panel.getByRole('button',{name:'確認した制作見積を保存',exact:true}).click();await expect(panel).toContainText('見積 1 作業日');await page.reload();const restored=(await backup(page)).project;expect(restored.entities.find(e=>e.id===f.task.id)).toMatchObject({data:{estimate:{value:1,speed:2,unknownCount:0,assumptions:['場面と台詞を固有件数で一度だけ制作']}}});});

test('旧媒体と元pinを保持し、未保存候補を再開して独立改訂・予定日・完全復元を確認する',async({page})=>{const f=story(),p=await createWorldSnapshot(f.p,'旧元設定'),pin=p.snapshots.at(-1)!,media=createEntity(p.projectId,'media_variant','公開済み小説',{medium:'novel',baseSnapshotId:pin.id,sourceIds:[f.scene.id],body:textToRichText('公開済みの旧本文'),releaseAt:'2026-10-09T01:00:00Z'});media.status='confirmed';p.entities.push(media);const current=p.entities.find(e=>e.id===f.scene.id)!;if(current.kind==='scene')current.data.body=textToRichText('元設定の新稿');await seed(page,p);async function open(){await nav(page,/^資料/);await page.getByLabel('情報の種類',{exact:true}).selectOption('media_variant');await page.locator('.entity-card').filter({has:page.getByRole('heading',{name:media.name,exact:true})}).click();}await open();let tool=page.locator('details').filter({has:page.locator('summary').filter({hasText:'媒体の旧公開版と改訂候補を比較'})});await tool.locator('summary').click();await tool.getByLabel('媒体の改訂候補本文',{exact:true}).fill('作者が書く改訂候補😀');await nav(page,/^構成/);await page.reload();await open();tool=page.locator('details').filter({has:page.locator('summary').filter({hasText:'媒体の旧公開版と改訂候補を比較'})});await tool.locator('summary').click();await expect(tool.getByLabel('媒体の改訂候補本文',{exact:true})).toHaveValue('作者が書く改訂候補😀');await tool.getByRole('button',{name:'媒体の改訂差分を確認',exact:true}).click();await expect(tool).toContainText('公開済みの旧本文');await expect(tool).toContainText('元設定の新稿');await quota(page);await tool.getByRole('button',{name:'旧媒体を保持して改訂候補を保存',exact:true}).click();await expect(tool.getByRole('alert')).toContainText('容量');await tool.getByRole('button',{name:'旧媒体を保持して改訂候補を保存',exact:true}).click();await tool.getByRole('button',{name:'保存した媒体改訂候補を開く',exact:true}).click();await expect(page.getByLabel('媒体の予定公開日時',{exact:true})).toHaveValue('2026-10-09T01:00:00Z');await page.reload();const restored=(await backup(page)).project;expect(restored.entities.find(e=>e.id===media.id)).toMatchObject({data:{body:[{text:'公開済みの旧本文'}],baseSnapshotId:pin.id}});expect(restored.entities.find(e=>e.kind==='media_variant'&&e.data.previousVariantId===media.id)).toMatchObject({status:'provisional',data:{body:[{text:'作者が書く改訂候補😀'}],needsReview:true}});expect(restored.snapshots.find(s=>s.id===pin.id)).toEqual(pin);});

test('相談MDの出所と対象版をcold再開し、作者別案へ保存・選択採用して正本と採用記録を復元する',async({page})=>{const f=story(),p=await createWorldSnapshot(f.p,'相談対象版'),pin=p.snapshots.at(-1)!;await seed(page,p);await output(page);let panel=page.locator('.consultation-import');await panel.locator('summary').click();await panel.getByLabel('提案の出所',{exact:true}).fill('作者が保存した相談.md');await panel.getByLabel('提案の相談対象版',{exact:true}).selectOption(pin.id);await panel.getByLabel('提案を比較する本文対象',{exact:true}).selectOption(f.scene.id);await panel.getByLabel('提案MDを選ぶ',{exact:true}).setInputFiles({name:'proposal.md',mimeType:'text/markdown',buffer:Buffer.from('😀別案の門を描く')});await expect(panel.getByLabel('提案Markdown',{exact:true})).toHaveValue('😀別案の門を描く');await nav(page,/^構成/);await page.reload();await output(page);panel=page.locator('.consultation-import');await panel.locator('summary').click();await expect(panel.getByLabel('提案の出所',{exact:true})).toHaveValue('作者が保存した相談.md');await panel.getByRole('button',{name:'提案の別案差分を確認',exact:true}).click();await quota(page);await panel.getByRole('button',{name:'提案を作者別案として保存',exact:true}).click();await expect(panel.getByRole('alert')).toContainText('容量');await panel.getByRole('button',{name:'提案を作者別案として保存',exact:true}).click();await expect(panel.getByRole('status')).toContainText('作者別案へ保存');await expect(panel.getByRole('button',{name:'提案の別案差分を確認',exact:true})).toBeEnabled();await holdFileRead(page,'second-proposal.md');await panel.getByLabel('提案MDを選ぶ',{exact:true}).setInputFiles({name:'second-proposal.md',mimeType:'text/markdown',buffer:Buffer.from('後続の別操作')});await nav(page,/^資料/);await output(page);panel=page.locator('.consultation-import');await panel.locator('summary').click();await expect(panel.getByRole('button',{name:'提案の別案差分を確認',exact:true})).toBeDisabled();await releaseFileRead(page);await expect(panel.getByLabel('提案Markdown',{exact:true})).toHaveValue('後続の別操作');await expect(panel.getByRole('button',{name:'提案の別案差分を確認',exact:true})).toBeEnabled();await nav(page,/^構成/);await page.getByRole('tab',{name:'作者別案',exact:true}).click();await page.getByLabel('別案内の編集対象',{exact:true}).selectOption(f.scene.id);await expect(page.getByLabel('別案内の場面本文',{exact:true})).toHaveValue('😀別案の門を描く');for(const change of await page.locator('.alternative-diff-list input[type=checkbox]').all())await change.check();await page.getByRole('button',{name:'選択した変更を正本へ採用',exact:true}).click();await expect(page.getByText(/正本へ採用した記録 1件/)).toBeVisible();await page.reload();const restored=(await backup(page)).project;expect(restored.entities.find(e=>e.id===f.scene.id)).toMatchObject({data:{body:[{text:'😀別案の門を描く'}]}});expect(restored.authorAlternatives?.[0].applyReceipts).toHaveLength(1);expect(restored.authorAlternatives?.[0].versions.at(-1)?.content.entities.find(e=>e.kind==='note')?.customValues).toMatchObject({consultationSource:'作者が保存した相談.md',consultationTargetVersionId:pin.id});});

test('通常出力を独立ゲームへ渡し、実勝利・経路・受領証跡を戻して原子保存・cold・完全復元する',async({page,context})=>{const f=story(),contract=createEntity(f.p.projectId,'external_contract','勝敗管理',{key:'game_result',owner:'game',inputType:'boolean',outputType:'boolean',version:'1.0.0',missingPolicy:'block',stubValues:[{type:'boolean',value:true},{type:'boolean',value:false}]});contract.status='confirmed';f.p.entities.push(contract);f.entry.data.gate={op:'external',contractId:contract.id};const profile=publicPolicy(f.p);await seed(page,f.p);await output(page);await page.getByLabel('出力目的',{exact:true}).selectOption('runtime_json');await page.getByRole('button',{name:'内容を検査・プレビュー',exact:true}).click();await expect(page.locator('.export-result')).toContainText('runtime.json');const exported=page.waitForEvent('download');await page.locator('.export-artifact').getByRole('button',{name:'この内容を保存',exact:true}).click();const bytes=await readFile((await (await exported).path())!),pkg=JSON.parse(bytes.toString());expect(pkg.runtimeProject).toBeTruthy();const game=await context.newPage();await game.goto(new URL('examples/browser-game/index.html',page.url()).href);await game.getByLabel('ゲームが受け取るruntime.json',{exact:true}).setInputFiles({name:'runtime.json',mimeType:'application/json',buffer:bytes});await expect(game.getByRole('status')).toContainText('受領hash');await game.getByRole('button',{name:`ゲームで勝利 (${contract.id})`,exact:true}).click();await expect(game.getByRole('status')).toContainText('actual');await game.getByRole('button',{name:'測定結果でゲームの物語を開始',exact:true}).click();await expect(game.getByText('😀帰ってきた',{exact:true})).toBeVisible();await game.getByRole('button',{name:'ゲームの規則で次へ',exact:true}).click();await expect(game.getByRole('status')).toContainText('terminal');const response=game.waitForEvent('download');await game.getByRole('button',{name:'受領hash・実結果の証跡を保存',exact:true}).click();const receiptBytes=await readFile((await (await response).path())!),receipt=JSON.parse(receiptBytes.toString());expect(receipt).toMatchObject({mode:'actual',status:'terminal',dialogueIds:[f.line.id]});await game.close();const panel=page.locator('.game-handoff');await panel.locator('summary').click();await panel.getByLabel('受渡しの公開範囲',{exact:true}).selectOption(profile.id);await panel.getByLabel('ゲームの受領証跡',{exact:true}).setInputFiles({name:'game-receipt.json',mimeType:'application/json',buffer:receiptBytes});await panel.getByRole('button',{name:'受領hash・ID対応・実結果を検証',exact:true}).click();await expect(panel).toContainText('実行証跡による分類 actual');await quota(page);await panel.getByRole('button',{name:'検証したゲーム受領を保存',exact:true}).click();await expect(panel.getByRole('alert')).toContainText('容量');await panel.getByRole('button',{name:'検証したゲーム受領を保存',exact:true}).click();await expect(panel.getByRole('status')).toContainText('表示版を確認');await expect(panel.getByRole('button',{name:'受領hash・ID対応・実結果を検証',exact:true})).toBeEnabled();await holdFileRead(page,'second-receipt.json');await panel.getByLabel('ゲームの受領証跡',{exact:true}).setInputFiles({name:'second-receipt.json',mimeType:'application/json',buffer:receiptBytes});await nav(page,/^資料/);await output(page);const reentered=page.locator('.game-handoff');await reentered.locator('summary').click();await expect(reentered.getByRole('button',{name:'受領hash・ID対応・実結果を検証',exact:true})).toBeDisabled();await releaseFileRead(page);await expect(reentered.getByRole('button',{name:'受領hash・ID対応・実結果を検証',exact:true})).toBeEnabled();await page.reload();const restored=(await backup(page)).project,note=restored.entities.find(e=>e.kind==='note'&&e.data.handoffReceipt);expect(note?.kind==='note'&&note.data.handoffReceipt).toMatchObject({mode:'actual',packageHash:receipt.packageHash,receiptHash:receipt.receiptHash});expect(restored.entities.find(e=>e.id===f.entry.id)?.data).toEqual(f.entry.data);});

test('通常画面で旧版と現稿の公開範囲を作り、固定引用のUnicode位置を試遊ZIPから開いて戻り、承認をcold復元する',async({page,context})=>{
 const f=story(),p=await createWorldSnapshot(f.p,'引用する旧本文'),pin=p.snapshots.at(-1)!,oldScene=pin.content.entities.find(entity=>entity.id===f.scene.id)!;if(oldScene.kind!=='scene')throw Error('fixture');const current=p.entities.find(entity=>entity.id===f.scene.id)!;if(current.kind!=='scene')throw Error('fixture');current.data.body=[{...textToRichText('😀現在稿から旧本文へ')[0],links:[{start:0,end:1,target:{entityId:f.scene.id,sourceVersionId:pin.id,blockId:oldScene.data.body[0].id,start:0,end:1}}]}];await seed(page,p);await output(page);
 async function createScope(title:string,version:string){const create=page.getByRole('button',{name:'公開範囲を作成',exact:true});if(await create.isVisible())await create.click();else await page.getByRole('button',{name:'新しい範囲',exact:true}).click();const modal=page.getByRole('dialog');await modal.getByLabel('公開範囲の元作品版',{exact:true}).selectOption(version);await modal.getByLabel('公開用の作品名',{exact:true}).fill(title);for(const entity of [f.scene,f.line,f.entry,f.terminal,f.edge,f.p.entities.find(entity=>entity.kind==='flow_graph')!])await modal.getByLabel('追加する対象',{exact:true}).selectOption(entity.id);await modal.getByLabel('選んだ対象の本文・表記を公開文へコピーする',{exact:true}).check();await modal.getByRole('button',{name:'範囲を作成して内容を確認',exact:true}).click();await expect(modal).toBeHidden();await page.getByLabel('情報の状態',{exact:true}).selectOption('confirmed');await expect(page.locator('.editor-save-state')).toContainText('端末内保存済み').catch(async cause=>{console.log('RB08_SCOPE_EDITOR_FAILURE',await page.locator('.detail-panel').innerText());throw cause;});const id=await page.locator('.detail-panel').getAttribute('data-entity-id');await page.getByRole('button',{name:'詳細を閉じる',exact:true}).click();const selected=await page.getByLabel('出力する公開範囲',{exact:true}).inputValue();expect(selected).toBeTruthy();return selected;}
 const child=await createScope('旧版の公開文',pin.id),root=await createScope('現在版の公開文','');await page.getByLabel('出力する公開範囲',{exact:true}).selectOption(root);await page.getByLabel('公開出力へ引用する固定版',{exact:true}).selectOption(pin.id);await page.getByLabel('引用版の確認済み公開範囲',{exact:true}).selectOption(child);await quota(page);await page.getByRole('button',{name:'この固定版の公開引用を保存',exact:true}).click();await expect(page.getByRole('alert')).toContainText('容量');await page.getByRole('button',{name:'この固定版の公開引用を保存',exact:true}).click();await expect(page.getByRole('button',{name:'引用承認を外す',exact:true})).toBeEnabled();await page.getByLabel('出力目的',{exact:true}).selectOption('playable_preview');await page.getByRole('button',{name:'内容を検査・プレビュー',exact:true}).click();await expect(page.locator('.export-result')).toContainText('playable-preview.zip');const pending=page.waitForEvent('download');await page.locator('.export-artifact').getByRole('button',{name:'この内容を保存',exact:true}).click();const files=unzipSync(new Uint8Array(await readFile((await(await pending).path())!))),htmlPath=join(await mkdtemp(join(tmpdir(),'rb08-citation-ui-')),'index.html');await writeFile(htmlPath,strFromU8(files['index.html']));const trial=await context.newPage();await trial.goto(pathToFileURL(htmlPath).href);await expect(trial.locator('#scene p').filter({hasText:'😀現在稿から旧本文へ'}).first()).toBeVisible().catch(async cause=>{console.log('RB08_CITATION_TRIAL_FAILURE',await trial.locator('body').innerText());throw cause;});const link=trial.getByRole('button',{name:'関連: 😀',exact:true});await link.click();await expect(trial.getByRole('dialog')).toContainText(oldScene.data.body[0].text);await expect(trial.getByRole('dialog').locator('mark')).toHaveText('😀');await trial.getByRole('button',{name:'元の読み位置へ戻る',exact:true}).click();await expect(link).toBeFocused();await trial.close();await page.reload();const restored=(await backup(page)).project,parent=restored.entities.find(entity=>entity.id===root);expect(parent?.kind==='projection_profile'&&parent.data.citedVersions).toMatchObject([{sourceVersionId:pin.id,profileId:child}]);
});

test('通常画面で企画・プレイ行動・実装作業を照合し、容量失敗後に対象版付き確認を保存しcold完全復元する',async({page})=>{
 const f=story(),spec=createEntity(f.p.projectId,'gameplay_spec','門のプレイ仕様',{sceneId:f.scene.id,action:textToRichText('門を押して勝利を確認する'),mechanic:'入力と勝敗の判定',tutorial:textToRichText('門を一回押す'),taskIds:[f.task.id],intentionalDifference:'本文は勝利、操作は勝敗の入力を確認する'}),brief=createEntity(f.p.projectId,'creative_brief','企画の判断元',{targetAudience:textToRichText('初めて読む人'),experience:textToRichText('分岐の意味を確かめる'),theme:textToRichText('判断'),tone:textToRichText('静か'),scope:textToRichText('一場面'),deliverableIds:[f.scene.id,spec.id]});spec.status=brief.status='confirmed';f.p.entities.push(spec,brief);await seed(page,f.p);await production(page);await expect(page.getByRole('heading',{name:'プレイヤーが行う行動'})).toBeVisible();await expect(page.getByText('門を押して勝利を確認する',{exact:true})).toBeVisible();await quota(page);await page.getByRole('button',{name:'遊びと物語の差を確認候補へ保存',exact:true}).click();await expect(page.getByRole('alert')).toContainText('容量');await page.getByRole('button',{name:'遊びと物語の差を確認候補へ保存',exact:true}).click();await expect(page.getByRole('button',{name:'遊びと物語の差を確認候補へ保存',exact:true})).toBeEnabled();await page.reload();const restored=(await backup(page)).project,review=restored.entities.find(entity=>entity.kind==='review'&&entity.name==='門のプレイ仕様 · 遊びと物語の差の確認');expect(review?.kind==='review'&&review.data.stage).toBe('open');if(review?.kind!=='review')throw Error('確認候補なし');expect(review.data.target).toBe(spec.id);const fixed=restored.snapshots.find(pin=>pin.id===review.data.targetVersionId);expect(fixed?.content.entities.find(entity=>entity.id===spec.id)).toMatchObject({data:{mechanic:'入力と勝敗の判定'}});expect(review.data.body?.map(block=>block.text).join('\n')).toContain('門を押して勝利を確認する');
});


test('通常出力の試遊ZIPが同じ素材IDの旧動画decodeと新音声bytesを別々に検証して固定参照から戻る',async({page,context})=>{
 const f=story(),old=await prepareAsset(new Uint8Array(await readFile('tests/fixtures/media/fixture-blue.mp4')),'旧動画'),{bytes:oldBytes,preview:_oldPreview,...oldMeta}=old,asset=createEntity(f.p.projectId,'attachment','公開する素材',oldMeta);asset.status='confirmed';f.p.entities.push(asset);const pinned=await createWorldSnapshot(f.p,'旧動画の版'),pin=pinned.snapshots.at(-1)!,newAsset=await prepareAsset(new Uint8Array(await readFile('tests/fixtures/media/fixture-tone.wav')),'新音声'),{bytes:newBytes,preview:_newPreview,...newMeta}=newAsset,current=pinned.entities.find(entity=>entity.id===asset.id)!;if(current.kind!=='attachment')throw Error('fixture');current.data=newMeta;const scene=pinned.entities.find(entity=>entity.id===f.scene.id)!;if(scene.kind!=='scene')throw Error('fixture');scene.data.body=[{...textToRichText('旧素材へ')[0],links:[{start:0,end:4,target:{entityId:asset.id,sourceVersionId:pin.id}}]}];
 function scope(records:typeof pinned.entities,version?:string){const publicTexts=Object.fromEntries(records.map(entity=>[entity.id,Object.fromEntries(Object.entries(entity.data).filter(([field,value])=>value!=null&&['body','text','key','label','terminalReason','description','displayName'].includes(field)).map(([field,value])=>[field,Array.isArray(value)?value.map(block=>({...block,id:newId()})):value]))])),policy=createEntity(pinned.projectId,'projection_profile','素材出力承認',{audience:'reader',publicTitle:'素材確認',includedIds:records.map(entity=>entity.id),allowedKinds:[...new Set(records.map(entity=>entity.kind))],idPolicy:'preserve',namePolicy:{defaultPolicy:{mode:'replace',replacement:'確認した素材と場面'}},publicTexts,approvedAttachmentIds:[asset.id],...(version?{sourceVersionId:version}:{})});policy.status='confirmed';pinned.entities.push(policy);return policy;}
 const child=scope(pin.content.entities.filter(entity=>entity.kind==='attachment'),pin.id),root=scope(pinned.entities.filter(entity=>['scene','dialogue_line','flow_node','flow_edge','flow_graph','attachment'].includes(entity.kind)));root.data.citedVersions=[{sourceVersionId:pin.id,profileId:child.id,publicVersionId:newId()}];await seed(page,pinned,{[oldMeta.contentHash]:oldBytes,[newMeta.contentHash]:newBytes});await output(page);await page.getByLabel('出力する公開範囲',{exact:true}).selectOption(root.id);await page.getByLabel('出力目的',{exact:true}).selectOption('playable_preview');await page.getByRole('button',{name:'内容を検査・プレビュー',exact:true}).click();await expect(page.locator('.export-result')).toContainText('playable-preview.zip');const download=page.waitForEvent('download');await page.locator('.export-artifact').getByRole('button',{name:'この内容を保存',exact:true}).click();const files=unzipSync(new Uint8Array(await readFile((await(await download).path())!))),htmlPath=join(await mkdtemp(join(tmpdir(),'rb08-old-material-')),'index.html');await writeFile(htmlPath,strFromU8(files['index.html']));const trial=await context.newPage();await trial.goto(pathToFileURL(htmlPath).href);await trial.getByRole('button',{name:'関連: 旧素材へ',exact:true}).click();await expect(trial.getByRole('dialog').locator('video')).toBeVisible();await expect.poll(()=>trial.getByRole('dialog').locator('video').evaluate((element:HTMLVideoElement)=>({width:element.videoWidth,height:element.videoHeight,duration:element.duration}))).toEqual({width:160,height:90,duration:0.5});await trial.getByRole('button',{name:'元の読み位置へ戻る',exact:true}).click();await expect(trial.getByRole('button',{name:'関連: 旧素材へ',exact:true})).toBeFocused();await trial.close();await page.reload();const restored=await backup(page);expect(restored.assets.map(asset=>asset.contentHash)).toEqual(expect.arrayContaining([oldMeta.contentHash,newMeta.contentHash]));
});
